// =============================================
// STEP 1: Confirm signal with Claude (2nd opinion)
// =============================================
const cfg = $getWorkflowStaticData('global');
const signal = $input.first().json;

const SYSTEM_PROMPT = `Ты — риск-менеджер торговой системы по методу Герчика.
Тебе дали торговый сигнал для подтверждения.

ПРОВЕРЬ:
1) Сигнал НЕ противоречит тренду на старшем ТФ?
2) Уровень действительно сильный (минимум 2 касания)?
3) Есть подтверждение на младшем ТФ (паттерн разворота)?
4) Risk/reward >= 3?
5) Стоп-лосс стоит за уровнем (за тенью свечи)?

ФОРМАТ ОТВЕТА строго JSON:
{
  "confirmed": true|false,
  "adjusted_entry": number или null,
  "adjusted_stop": number или null,
  "adjusted_tp1": number или null,
  "risk_score": 1-10,
  "reasoning": "объяснение на русском"
}

ВАЖНО: Отвечай ТОЛЬКО валидным JSON.`;

try {
  const response = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://openrouter.ai/api/v1/chat/completions',
    headers: {
      'Authorization': `Bearer ${cfg.OPENROUTER_API_KEY}`,
      'Content-Type': 'application/json'
    },
    body: {
      model: cfg.OPENROUTER_MODEL || 'anthropic/claude-sonnet-4-20250514',
      max_tokens: 512,
      messages: [
        { role: 'system', content: SYSTEM_PROMPT },
        { role: 'user', content: `Подтверди сигнал:\n${JSON.stringify(signal, null, 2)}` }
      ]
    }
  });

  const text = response.choices[0].message.content;
  let jsonStr = text;
  const jsonMatch = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (jsonMatch) jsonStr = jsonMatch[1];

  const confirmation = JSON.parse(jsonStr.trim());

  return [{
    json: {
      ...signal,
      _confirmation: confirmation,
      _confirmed: confirmation.confirmed === true && confirmation.risk_score <= 7,
      entry_price: confirmation.adjusted_entry || signal.entry_price,
      stop_loss: confirmation.adjusted_stop || signal.stop_loss,
      take_profit_1: confirmation.adjusted_tp1 || signal.take_profit_1
    }
  }];
} catch(e) {
  // Claude unavailable — DO NOT TRADE
  return [{
    json: {
      ...signal,
      _confirmed: false,
      _confirmation: { confirmed: false, reasoning: `OpenRouter API error: ${e.message}` },
      _error: true
    }
  }];
}

