// =============================================
// STEP 4: Place order + SL + TP on Bybit
// =============================================
const cfg = $getWorkflowStaticData('global');
const data = $input.first().json;

if (data._skip) {
  return [{ json: { ...data, orderResult: 'SKIPPED', orderReason: data._skipReason } }];
}

const apiKey = cfg.BYBIT_API_KEY;
const apiSecret = cfg.BYBIT_API_SECRET;
const baseUrl = data.baseUrl;

async function signedPost(endpoint, body) {
  const timestamp = Date.now().toString();
  const recvWindow = '5000';
  const bodyStr = JSON.stringify(body);
  const preSign = timestamp + apiKey + recvWindow + bodyStr;
  const signature = hmacSHA256(apiSecret, preSign);

  return this.helpers.httpRequest({
    method: 'POST',
    url: `${baseUrl}${endpoint}`,
    headers: {
      'X-BAPI-API-KEY': apiKey,
      'X-BAPI-SIGN': signature,
      'X-BAPI-TIMESTAMP': timestamp,
      'X-BAPI-RECV-WINDOW': recvWindow,
      'Content-Type': 'application/json'
    },
    body
  });
}

const category = data.market_type === 'futures' ? 'linear' : 'spot';
const isSpot = category === 'spot';

try {
  // Main order with SL/TP
  const orderPayload = {
    category,
    symbol: data.pair,
    side: data.action, // Buy or Sell
    orderType: 'Limit',
    qty: data.positionSize.toString(),
    price: data.entry_price.toString(),
    timeInForce: 'GTC',
    ...(isSpot ? {} : {
      stopLoss: data.stop_loss.toString(),
      takeProfit: data.take_profit_1.toString(),
      tpslMode: 'Full',
      tpOrderType: 'Limit',
      slOrderType: 'Market'
    })
  };

  const orderResp = await signedPost.call(this, '/v5/order/create', orderPayload);

  // For spot — place separate SL order via conditional order
  let slOrderId = null;
  if (isSpot && orderResp.retCode === 0) {
    const slSide = data.action === 'Buy' ? 'Sell' : 'Buy';
    const slPayload = {
      category: 'spot',
      symbol: data.pair,
      side: slSide,
      orderType: 'Market',
      qty: data.positionSize.toString(),
      triggerPrice: data.stop_loss.toString(),
      triggerDirection: data.action === 'Buy' ? 2 : 1, // 1=rise, 2=fall
      orderFilter: 'StopOrder'
    };
    try {
      const slResp = await signedPost.call(this, '/v5/order/create', slPayload);
      slOrderId = slResp.result?.orderId || null;
    } catch(e) { /* SL order failed — will alert */ }
  }

  return [{
    json: {
      ...data,
      orderResult: orderResp.retCode === 0 ? 'SUCCESS' : 'FAILED',
      orderId: orderResp.result?.orderId || 'N/A',
      slOrderId,
      retCode: orderResp.retCode,
      retMsg: orderResp.retMsg
    }
  }];
} catch(e) {
  return [{
    json: {
      ...data,
      orderResult: 'ERROR',
      orderId: 'N/A',
      retMsg: e.message
    }
  }];
}

// =============================================
// STEP 5: Format Telegram notification
// =============================================
const cfg = $getWorkflowStaticData('global');
const data = $input.first().json;

const success = data.orderResult === 'SUCCESS';
const emoji = success ? '✅' : '❌';
const sideEmoji = data.action === 'Buy' ? '🟢 LONG' : '🔴 SHORT';

let message = `${emoji} <b>Trade Executor</b>\n\n`;
message += `${sideEmoji} <b>${data.pair}</b>\n\n`;

if (success) {
  message += `<b>Вход:</b> <code>${data.entry_price}</code>\n`;
  message += `<b>Стоп:</b> <code>${data.stop_loss}</code>\n`;
  message += `<b>TP1:</b> <code>${data.take_profit_1}</code>\n`;
  message += `<b>TP2:</b> <code>${data.take_profit_2}</code>\n`;
  message += `<b>TP3:</b> <code>${data.take_profit_3}</code>\n\n`;
  message += `<b>Размер:</b> ${data.positionSize} (~$${data.positionValue})\n`;
  message += `<b>Риск:</b> $${data.riskAmount} (${data.riskPercent}%)\n`;
  message += `<b>R:R:</b> ${data.risk_reward_ratio}\n`;
  message += `<b>Уверенность:</b> ${data.confidence}%\n`;
  message += `<b>Order ID:</b> <code>${data.orderId}</code>\n\n`;
  message += `<b>Причина:</b> ${data.reasoning}\n`;
  message += `<b>Подтверждение:</b> ${data._confirmation?.reasoning || 'N/A'}\n`;
} else {
  message += `<b>Ошибка:</b> ${data.retMsg || data.orderResult}\n`;
  if (data._skipReason) message += `<b>Причина пропуска:</b> ${data._skipReason}\n`;
}

message += `\n<b>Баланс:</b> $${data.usdtBalance?.toFixed(2)}\n`;
message += `<b>Позиций:</b> ${data.openPositions}/${data.maxPositions}\n`;
message += `⏱ ${new Date().toLocaleString('ru-RU', { timeZone: 'Europe/Moscow' })}`;

return [{ json: { message } }];
